def _occ_shapes_for_object(obj: Any, _depth: int = 0) -> List[Any]:
    """Return OCC B-Rep shapes for *obj*, recursively resolving boolean results.

    Resolution order (mirrors FreeCAD's Part workbench):
      1. Cached ``occ_shape`` attribute on the object.
      2. Boolean result: rebuild operands recursively then apply OCC boolean API.
      3. Original STEP source file re-read by solid name.

    *_depth* guards against infinite recursion in pathological graphs.
    """
    if _depth > 8:
        return []

    # 1. Cached B-Rep shape (fastest path).
    occ_shape = getattr(obj, "occ_shape", None)
    if occ_shape is not None:
        return [occ_shape]

    # 2. Boolean result — reconstruct at B-Rep level.
    boolean_op = str(getattr(obj, "boolean_op", "") or "").strip().lower()
    if boolean_op in ("fuse", "cut", "common"):
        source_objects = list(getattr(obj, "source_objects", None) or [])
        if len(source_objects) >= 2:
            rebuilt = _build_boolean_occ_shape(boolean_op, source_objects, _depth + 1)
            if rebuilt is not None:
                return [rebuilt]

    # 3. Original STEP source.
    return _occ_shapes_from_step_source(obj)


def _apply_occ_boolean(op: str, s1: Any, s2: Any) -> Any | None:
    """Apply a single OCC boolean operation between two shapes.

    Tries OCP (open-cascade-occt) first, then pythonOCC-core as fallback.
    Returns None if neither backend is available or the operation fails.
    """
    for _pkg in ("OCP", "OCC.Core"):
        try:
            if _pkg == "OCP":
                from OCP.BRepAlgoAPI import BRepAlgoAPI_Fuse, BRepAlgoAPI_Cut, BRepAlgoAPI_Common
            else:
                from OCC.Core.BRepAlgoAPI import BRepAlgoAPI_Fuse, BRepAlgoAPI_Cut, BRepAlgoAPI_Common

            if op == "fuse":
                builder = BRepAlgoAPI_Fuse(s1, s2)
            elif op == "cut":
                builder = BRepAlgoAPI_Cut(s1, s2)
            else:  # common
                builder = BRepAlgoAPI_Common(s1, s2)

            builder.Build()
            if not builder.IsDone():
                return None
            return builder.Shape()
        except ImportError:
            continue
        except Exception:
            return None
    return None


def _build_boolean_occ_shape(op: str, source_objects: list, depth: int) -> Any | None:
    """Collect OCC shapes for every source object and fold them with *op*."""
    all_shapes: List[Any] = []
    for src in source_objects:
        shapes = _occ_shapes_for_object(src, depth)
        if not shapes:
            return None  # Need every operand — bail so mesh fallback is used.
        all_shapes.extend(shapes)

    if len(all_shapes) < 2:
        return None

    result = all_shapes[0]
    for s in all_shapes[1:]:
        result = _apply_occ_boolean(op, result, s)
        if result is None:
            return None
    return result


def _try_write_boolean_brep_step(obj: Any, step_path: Path) -> bool:
    """FreeCAD-style boolean export: redo the boolean at OCC B-Rep level.

    FreeCAD's Part workbench keeps a TopoDS_Shape throughout the whole workflow
    and applies BRepAlgoAPI_Fuse / BRepAlgoAPI_Cut / BRepAlgoAPI_Common on the
    analytical B-Rep, never touching a mesh.  We replicate that here:

      source solid A (read from .step) ──┐
                                          ├─ BRepAlgoAPI_Fuse ─► STEPControl_Writer
      source solid B (read from .step) ──┘

    Result: one MANIFOLD_SOLID_BREP with analytic faces — compact file, 1 solid.
    Returns True on success; caller falls back to mesh path on False.
    """
    boolean_op = str(getattr(obj, "boolean_op", "") or "").strip().lower()
    if boolean_op not in ("fuse", "cut", "common"):
        return False

    source_objects = list(getattr(obj, "source_objects", None) or [])
    if len(source_objects) < 2:
        return False

    result_shape = _build_boolean_occ_shape(boolean_op, source_objects, 0)
    if result_shape is None:
        return False

    try:
        _write_step_from_occ_shape(result_shape, step_path)
        return step_path.exists() and step_path.stat().st_size > 0
    except Exception:
        return False


