def _try_write_step_from_original_source(obj: Any, actor: vtk.vtkActor, step_path: Path) -> bool:
    """Best-effort direct STEP solid reuse from original imported source.

    Uses the per-run shape-index cache so the source file is parsed at most
    once per export run, regardless of how many objects share it.
    """
    source = getattr(obj, "step_source_path", None)
    solid_name = getattr(obj, "step_solid_name", None)
    source_parts = getattr(obj, "step_source_parts", None)
    if not source:
        return False

    source_path = Path(str(source))
    if not source_path.exists() or not _is_identity_actor_transform(actor):
        return False

    target_candidates: List[str] = []
    if isinstance(source_parts, list) and source_parts:
        for part in source_parts:
            target_candidates.extend(_candidate_source_solid_names(str(part)))
    elif solid_name:
        target_candidates.extend(_candidate_source_solid_names(str(solid_name)))

    seen_c: set[str] = set()
    target_candidates = [c for c in target_candidates if not (c in seen_c or seen_c.add(c))]  # type: ignore[func-returns-value]
    if not target_candidates:
        return False

    index = _get_shape_index(source_path)
    shapes_to_write = _resolve_shapes_from_index(index, target_candidates)
    if not shapes_to_write:
        return False

    for _pkg in ("OCP", "OCC.Core"):
        try:
            if _pkg == "OCP":
                from OCP.STEPControl import STEPControl_Writer, STEPControl_AsIs
            else:
                from OCC.Core.STEPControl import STEPControl_Writer, STEPControl_AsIs
            writer = STEPControl_Writer()
            for shape in shapes_to_write:
                writer.Transfer(shape, STEPControl_AsIs)
            return int(writer.Write(str(step_path))) == 1
        except ImportError:
            continue
        except Exception:
            return False
    return False

def _occ_shapes_from_step_source(obj: Any) -> List[Any]:
    """Read OCC shapes for *obj* from its original STEP source file.

    Uses the per-run shape-index cache — the file is parsed at most once.
    """
    source = getattr(obj, "step_source_path", None)
    if not source:
        return []
    source_path = Path(str(source))
    if not source_path.exists():
        return []

    solid_name = getattr(obj, "step_solid_name", None)
    source_parts = getattr(obj, "step_source_parts", None)

    target_candidates: List[str] = []
    if isinstance(source_parts, list) and source_parts:
        for part in source_parts:
            target_candidates.extend(_candidate_source_solid_names(str(part)))
    elif solid_name:
        target_candidates.extend(_candidate_source_solid_names(str(solid_name)))

    if not target_candidates:
        return []

    seen_c: set[str] = set()
    target_candidates = [c for c in target_candidates if not (c in seen_c or seen_c.add(c))]  # type: ignore[func-returns-value]

    index = _get_shape_index(source_path)
    return _resolve_shapes_from_index(index, target_candidates)

def _try_boolean_from_source_parts(boolean_op: str, source_path: Path, part_names: List[str]) -> Any | None:
    """Read each named solid from *source_path* and fold them with *boolean_op*.

    Reload-safe path: works from StepSourcePath + StepSourceParts which are
    stored in the .em3d JSON.  Uses the per-run shape-index cache so the file
    is parsed at most once even when many boolean results share the same source.
    """
    if not source_path.exists() or len(part_names) < 2:
        return None

    per_part_candidates: List[List[str]] = []
    for name in part_names:
        cands = _candidate_source_solid_names(name)
        if cands:
            per_part_candidates.append(cands)

    if len(per_part_candidates) < 2:
        return None

    index = _get_shape_index(source_path)
    if not index:
        return None

    operands: List[Any] = []
    seen_ids: set[int] = set()
    for candidates in per_part_candidates:
        for cand in candidates:
            s = index.get(cand)
            if s is not None and id(s) not in seen_ids:
                seen_ids.add(id(s))
                operands.append(s)
                break

    if len(operands) < 2:
        return None

    result = operands[0]
    for s in operands[1:]:
        result = _apply_occ_boolean(boolean_op, result, s)
        if result is None:
            return None
    return result

data.content:
Ho proseguito con il necessario per rendere il nuovo export STEP non solo più compatto, ma anche geometricamente corretto dopo trasformazioni.

Il punto chiave era questo: dopo `move` / `rotate` / `mirror`, molti oggetti diventavano `MeshObject` ma per l’export conservavano solo il legame alla sorgente STEP o al booleano, senza conservare la trasformazione o la ricetta del solido originale. Risultato: il builder OCC poteva ricostruire una shape “pulita”, ma nella posa sbagliata. Ho corretto questo introducendo metadati persistenti su [src/em3d_modeler/scene/em_objects.py](src/em3d_modeler/scene/em_objects.py): `export_recipe_type`, `export_recipe_params`, `export_transform_matrix`. Poi ho aggiornato [src/em3d_modeler/scene/scene_manager.py](src/em3d_modeler/scene/scene_manager.py) perché `move`, `rotate`, `mirror` e le ricostruzioni di `MeshObject` compongano e serializzino questi metadati invece di lasciare una lineage OCC stale.

Sul lato export, [src/em3d_modeler/emerge/occ_export_builder.py](src/em3d_modeler/emerge/occ_export_builder.py) ora fa tre cose in più:
- ricostruisce shape OCC anche da una recipe persistita quando un primitive è stato convertito in `MeshObject`;
- applica la matrice affine salvata alla shape finale, anche per booleani e STEP importati trasformati;
- usa trasformazioni affini generali (`GTransform`) invece del solo path rigido, così anche i mirror vengono trattati in modo coerente.

Verifica eseguita:
- nessun errore statico nei file toccati;
- import runtime OK per scene manager, em_objects e nuovo builder OCC.

Resta ancora naturale fare un ultimo giro di pulizia su [src/em3d_modeler/emerge/step_bundle_exporter.py](src/em3d_modeler/emerge/step_bundle_exporter.py) per rimuovere parte del vecchio codice ridondante adesso che il percorso OCC-first è quello principale. Se vuoi, procedo con quello come prossimo step.

Corretto: ora lo script esportato non si blocca più su `VersionError` quando il runtime EMERGE è più nuovo.

Ho modificato il generatore in modo che:
- faccia comunque il check versione;
- in caso di mismatch, per default mostri solo un warning e continui;
- puoi riattivare il comportamento bloccante impostando `STRICT_VERSION_CHECK = True` nello script generato.

Se vuoi, nel prossimo step posso anche aggiungere un’opzione UI/progetto per scegliere questo comportamento senza toccare manualmente lo script.

